import { useEffect, useState } from 'react';
import { api } from '../api/client.js';
import { MovieMiniCard } from './MovieCard.jsx';
import { Badge } from './ui.jsx';

const EXAMPLES = [
  'A funny action movie around 2 hours',
  'Something for the whole family',
  'A tense sci-fi thriller',
  'An emotional drama under 2.5 hours',
];

/**
 * AI movie recommendation.
 *
 * Talks to POST /api/ai/recommend, which is the only place OpenRouter is used
 * for this feature. The response always says where the answer came from, so the
 * UI never pretends a fallback result was generated by the model.
 */
export default function AiRecommendStrip() {
  const [status, setStatus] = useState(null);
  const [query, setQuery] = useState('');
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    api.aiStatus().then((response) => setStatus(response.data)).catch(() => setStatus({ enabled: false }));
  }, []);

  const ask = async (text) => {
    const trimmed = (text ?? query).trim();
    if (trimmed.length < 3 || busy) return;
    setBusy(true);
    setError(null);
    try {
      const response = await api.aiRecommend({ query: trimmed, limit: 3 });
      setResult(response.data);
      setQuery(trimmed);
    } catch (caught) {
      setError(caught);
      setResult(null);
    } finally {
      setBusy(false);
    }
  };

  const isAi = result?.source === 'openrouter';

  return (
    <section className="ai-strip">
      <div>
        <div className="row gap-8 wrap" style={{ marginBottom: 10 }}>
          <Badge tone="soon">✨ AI</Badge>
          {status ? (
            <Badge tone={status.enabled ? 'live' : 'warn'}>
              {status.enabled ? `Live · ${status.model}` : 'Offline — built-in matcher'}
            </Badge>
          ) : null}
        </div>

        <h2>Tell us what you feel like watching</h2>
        <p className="muted small" style={{ marginBottom: 16 }}>
          Describe a mood, a genre or a length and we will pick from the films actually on our
          catalogue. Recommendations never invent a movie that is not on sale here.
        </p>

        <form
          className="row gap-8"
          onSubmit={(event) => {
            event.preventDefault();
            ask();
          }}
        >
          <input
            className="input"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
            placeholder="e.g. a funny action movie around 2 hours"
            aria-label="Describe what you want to watch"
          />
          <button type="submit" className="btn btn-accent nowrap" disabled={busy || query.trim().length < 3}>
            {busy ? <span className="spinner" style={{ width: 15, height: 15 }} /> : '✨'}
            {busy ? 'Thinking' : 'Suggest'}
          </button>
        </form>

        <div className="row gap-8 wrap" style={{ marginTop: 12 }}>
          {EXAMPLES.map((example) => (
            <button
              key={example}
              type="button"
              className="ai-suggestion"
              onClick={() => ask(example)}
              disabled={busy}
            >
              {example}
            </button>
          ))}
        </div>
      </div>

      <div className="ai-results">
        {error ? (
          <div className="alert alert-error">
            <span aria-hidden="true">⚠️</span>
            <div>
              <strong>Could not reach the recommendation service</strong>
              <div className="small">{error.message}</div>
            </div>
          </div>
        ) : null}

        {!result && !error ? (
          <div className="card card-pad-sm" style={{ display: 'grid', placeItems: 'center', minHeight: 190, textAlign: 'center' }}>
            <div>
              <div style={{ fontSize: '1.7rem', marginBottom: 8 }} aria-hidden="true">🍿</div>
              <p className="small dim" style={{ maxWidth: '34ch' }}>
                Your suggestions appear here. Nothing you type here can change prices, seats or bookings.
              </p>
            </div>
          </div>
        ) : null}

        {result ? (
          <>
            <div className={`alert ${isAi ? 'alert-info' : 'alert-warn'}`}>
              <span aria-hidden="true">{isAi ? '✨' : 'ℹ️'}</span>
              <div>
                <strong>{isAi ? `AI suggestion${result.model ? ` · ${result.model}` : ''}` : 'Built-in matcher'}</strong>
                <p className="small" style={{ marginTop: 3 }}>{result.summary}</p>
                {result.notice ? <p className="tiny" style={{ marginTop: 6, opacity: 0.85 }}>{result.notice}</p> : null}
              </div>
            </div>
            {result.movies.map((movie) => (
              <MovieMiniCard key={movie.id} movie={movie} reason={movie.reason} />
            ))}
          </>
        ) : null}
      </div>
    </section>
  );
}
